namespace Metalama.Samples.Authorization;

/// <summary>
/// The run-time entry point of the framework. The code generated by <see cref="RequiresPermissionAttribute"/>
/// calls <see cref="Demand"/> before each secured operation.
/// </summary>
public static class AccessGuard
{
    /// <summary>
    /// Throws an <see cref="AccessDeniedException"/> if the current subject does not have the permission
    /// on <paramref name="securable"/>.
    /// </summary>
    /// <param name="securable">The object being accessed, or the argument for a parameter check.</param>
    /// <param name="permission">The name of the required permission.</param>
    /// <param name="member">The name of the member being accessed, for messages and audit.</param>
    /// <param name="accessKind">The kind of access.</param>
    /// <exception cref="InvalidOperationException">There is no current security context.</exception>
    public static void Demand( ISecurable securable, string permission, string member, AccessKind accessKind )
    {
        if ( SecurityContext.IsSystem )
        {
            return;
        }

        // An object that is being initialized is set up by its creator with unlimited rights, and is not usable by
        // anybody else (see SecurityContext.BeginInitialization).
        if ( SecurityContext.TryGetInitializationState( securable, out var initializationState ) )
        {
            DemandDuringInitialization( securable, permission, member, accessKind, initializationState );

            return;
        }

        var context = GetContext( member );
        Permission requiredPermission = permission;

        // The decision is cached in the current execution context (see SecurityContext). Each access is still
        // audited, because the auditor records accesses, not decisions.
        if ( !SecurityContext.TryGetCachedDecision( securable, requiredPermission, out var isGranted ) )
        {
            // The policy reads secured members, for instance the owner of the object.
            // Running it in a system scope avoids recursive checks.
            using ( SecurityContext.RunAsSystem() )
            {
                // A grant of a member that is running (see GrantsPermissionsAttribute) takes precedence over the policy.
                isGranted = SecurityContext.IsGranted( securable, requiredPermission )
                            || context.Policy.IsGranted( context.Subject, requiredPermission, securable );
            }

            SecurityContext.CacheDecision( securable, requiredPermission, isGranted );
        }

        if ( !isGranted )
        {
            Fail( context, CreateRecord( context, securable, requiredPermission, member, accessKind ), null );
        }

        // An access that changes the rights makes the cached decisions wrong: the cache of the execution context is
        // cleared, and the decisions on the object are removed from the shared cache. The access is checked before the
        // change, so the next check sees the change.
        if ( IsRightsChanging( requiredPermission ) )
        {
            SecurityContext.ClearCachedDecisions();
            (context.Policy as CachingAuthorizationPolicy)?.Invalidate( securable );
        }

        AuditGrant( context, securable, requiredPermission, member, accessKind );
    }

    private static void DemandDuringInitialization(
        ISecurable securable,
        Permission permission,
        string member,
        AccessKind accessKind,
        InitializationState state )
    {
        // While the constructors run, the creator has unlimited rights. After them, it can only set properties, as the
        // object initializer does. The access is not cached, but it is audited like a grant.
        if ( SecurityContext.IsInitializing( securable )
             && (state == InitializationState.Constructing || accessKind == AccessKind.Write) )
        {
            AuditGrant( GetContext( member ), securable, permission, member, accessKind );

            return;
        }

        throw new InvalidOperationException(
            $"Cannot access {member}: the object is not initialized. Its initialization ends after the object initializer, " +
            $"at a call site compiled by Metalama. An object created in another way, for instance by reflection, must be " +
            $"initialized with {nameof(ISecurable)}.{nameof(ISecurable.CompleteInitialization)}." );
    }

    // The permissions whose operations change the owner or the role assignments of an object, which the role-based
    // policy reads.
    private static bool IsRightsChanging( Permission permission )
        => permission.Name is PermissionNames.ChangeOwnership or PermissionNames.ManageRoles;

    // The auditor runs with the permissions of the subject, outside of the system scope.
    private static void AuditGrant( ISecurityContext context, ISecurable securable, Permission permission, string member, AccessKind accessKind )
    {
        if ( context.Auditor?.AuditsGrantsOf( permission ) == true )
        {
            context.Auditor.OnAccessGranted( CreateRecord( context, securable, permission, member, accessKind ) );
        }
    }

    // The label reads secured members, so it is computed in a system scope.
    private static AccessRecord CreateRecord( ISecurityContext context, ISecurable securable, Permission permission, string member, AccessKind accessKind )
    {
        using ( SecurityContext.RunAsSystem() )
        {
            return new AccessRecord( context.Subject, permission, SecurityLabel.Of( securable ), member, accessKind );
        }
    }

    /// <summary>
    /// Denies an operation for a reason that is not a missing permission, for instance because a user tries to
    /// assign a role to themself. The denial is audited like any other.
    /// </summary>
    /// <param name="securable">The object being accessed.</param>
    /// <param name="permission">The permission of the operation.</param>
    /// <param name="member">The name of the member being accessed.</param>
    /// <param name="reason">The reason of the denial, included in the exception message.</param>
    public static void Deny( ISecurable securable, string permission, string member, string reason )
    {
        var context = GetContext( member );

        AccessRecord record;

        using ( SecurityContext.RunAsSystem() )
        {
            record = new AccessRecord( context.Subject, permission, SecurityLabel.Of( securable ), member, AccessKind.Execute );
        }

        Fail( context, record, reason );
    }

    private static ISecurityContext GetContext( string member )
        // Fail closed: a missing context is a configuration error, not a reason to skip security.
        => SecurityContext.Current
           ?? throw new InvalidOperationException(
               $"Cannot access {member}: there is no current security context. " +
               "Use SecurityContext.Use() or SecurityContext.RunAsSystem()." );

    private static void Fail( ISecurityContext context, AccessRecord record, string? reason )
    {
        var exception = new AccessDeniedException( record, reason );
        context.Auditor?.OnAccessDenied( exception );

        throw exception;
    }
}
